const b = $input.first().json.body;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const keys = Object.keys(b?.association ?? {}).sort().join(',');
const associationOk = b?.association?.state === 'UNASSIGNED' ? keys === 'state' : b?.association?.state === 'ASSIGNED' && keys === 'clientCode,state' && /^CLI-[0-9]{4}-[A-Z]{2}-[0-9]{6}$/.test(b.association.clientCode ?? '');
if (!b || !/^[a-f0-9]{64}$/.test(b.jobId ?? '') || !uuid.test(b.representativeId ?? '') || !associationOk || b.recipient !== 'recette@example.invalid' ||
typeof b.subject !== 'string' || b.subject.trim() !== b.subject || !/^Tonia — TEST LOCAL — synthèse mobile [a-f0-9]{8}$/.test(b.subject) ||
typeof b.text !== 'string' || !b.text.trim() || b.text.length > 650000) throw new Error('Capture Mailpit invalide.');
return [{json:{recipient:'recette@example.invalid',subject:b.subject,text:b.text}}];

const info = $input.first().json;
const recipient = $('Verifier envoi').first().json.recipient;
if (typeof info.messageId !== 'string' || !info.messageId || !Array.isArray(info.accepted) ||
!info.accepted.some(address => typeof address === 'string' && address.toLowerCase() === recipient.toLowerCase()) ||
(Array.isArray(info.rejected) && info.rejected.length)) throw new Error('Acceptation SMTP non confirmée.');
return [{json:{accepted:true,deliveryMode:'MAILPIT',messageId:info.messageId}}];
